"""Level-2 questions for module 09 (PCBs and ESD, EASA M04 SM02): the module had only 16 level-2 questions (6 of them trace-resistance sums), the rest were recall (level 1).
Level 2 here means understanding or applying what the pages say: a scenario to judge (which parts can a 1 500 V person damage?), a cause and effect, an ordering, a comparison, a unit
conversion or a ratio taken from the text.  Every question carries an evidence pattern that must occur on the cited PDF page of the EASA OCR text (checked here and again by
build/verify/verify_m09.py); numeric answers are computed in this script.
Output: data/qsrc/m09_zl2.json and data/verify/m09_l2_evidence.json.   Run: python3 -I build/gen/gen_m09_l2.py && python3 build/assemble.py"""
import os, sys, json, re, math, subprocess
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
PDF = os.path.join(ROOT, '..', 'pdf_ocr_fixed', 'EASA_M04_Electronics_Fundamentals_ocr.pdf')
_pg = {}
def page_text(n):
    if n not in _pg: _pg[n] = re.sub(r'\s+', ' ', subprocess.run(['pdftotext', '-f', str(n), '-l', str(n), PDF, '-'], capture_output=True, text=True).stdout)
    return _pg[n]
TOP = {}
for it in json.load(open(os.path.join(ROOT, 'data', 'qbank', 'm09.json'), encoding='utf-8'))['items']: TOP[it['topic']['en']] = it['topic']
ITEMS = []; EV = {}
def Q(topic, page, rx, q, opts, expl):
    """q = (en, vi); opts = [(en, vi), ...] with the CORRECT option first; expl = (en, vi)."""
    assert re.search(rx, page_text(page), re.I), ('evidence not on the page', page, rx)
    assert len({o[0] for o in opts}) == len(opts) == 4, q[0]
    pr = f'2.{page - 87}'
    ITEMS.append(dict(kind='mcq', q=dict(en=q[0], vi=q[1]), opts=[dict(en=o[0], vi=o[1]) for o in opts], correct=0, explain=dict(en=expl[0], vi=expl[1]), level=2, topic=TOP[topic],
                      src=dict(en=f'EASA M04 SM02, p.{pr} (PDF p.{page})', vi=f'EASA M04 SM02, tr.{pr} (PDF tr.{page})'), origin='bo_sung', fixed_order=False, check='EASA text', tags=['l2']))
    EV[q[0]] = dict(page=page, rx=rx)
ST, ES, MT, ML, PC, RP = 'Static electricity and ESD', 'ESD protection and handling', 'Mounting technologies and soldering', 'Multilayer boards and vias', 'PCB construction and materials', 'PCB repair and LRMs'
# ------------------------------------------------------------------ static electricity and ESD (p.2.6, PDF 93)
r = 35000 / 1500; assert round(r) == 23
Q(ST, 93, r'35\s*000\s+volts\s+of\s+static\s+electricity\s+at\s+20%', ('How many times larger is the static voltage produced by walking on a carpet at 20 % relative humidity (up to 35,000 V) than at 65 % relative humidity (1,500 V)?', 'Đi trên thảm ở độ ẩm tương đối 20 % (tới 35.000 V) cho điện áp tĩnh lớn gấp bao nhiêu lần so với ở độ ẩm 65 % (1.500 V)?'),
  [('About 23 times', 'Khoảng 23 lần'), ('About 2.3 times', 'Khoảng 2,3 lần'), ('About 230 times', 'Khoảng 230 lần'), ('About 13 times', 'Khoảng 13 lần')],
  ('35,000 V ÷ 1,500 V = 23.3: dry air multiplies the charge by more than twenty, which is why humidity and conductive floors matter.', '35.000 V ÷ 1.500 V = 23,3: không khí khô làm điện tích tăng hơn hai mươi lần, đó là lý do độ ẩm và sàn dẫn điện quan trọng.'))
Q(ST, 93, r'bi-polar\s+transistors\s+are\s+susceptible\s+to\s+ESD\s+between\s+380', ('A technician has walked across a carpet at 65 % humidity and carries about 1,500 V. Using the damage ranges in the text (bipolar 380–7,000 V, CMOS 250–3,000 V, EPROM from 100 V), which parts can he damage by touching them?', 'Một kỹ thuật viên vừa đi trên thảm ở độ ẩm 65 % và mang khoảng 1.500 V. Theo các khoảng gây hỏng trong sách (lưỡng cực 380–7.000 V, CMOS 250–3.000 V, EPROM từ 100 V), anh ấy có thể làm hỏng những linh kiện nào khi chạm vào?'),
  [('Bipolar transistors, CMOS devices and EPROMs', 'Transistor lưỡng cực, linh kiện CMOS và EPROM'), ('Only EPROMs', 'Chỉ EPROM'), ('CMOS devices and EPROMs but not bipolar transistors', 'CMOS và EPROM nhưng không phải transistor lưỡng cực'), ('No type: 1,500 V is below every threshold', 'Không loại nào: 1.500 V thấp hơn mọi ngưỡng')],
  ('1,500 V is above the lowest damaging voltage of all three families (380 V, 250 V, 100 V), so all of them are at risk.', '1.500 V lớn hơn điện áp gây hỏng thấp nhất của cả ba họ (380 V, 250 V, 100 V), nên cả ba đều có nguy cơ.'))
Q(ST, 93, r'EPROMs,\s+used\s+in\s+computer\s+memories,\s+are\s+susceptible', ('A person carries only 200 V. Which of these parts can still be damaged (lowest damaging voltage: bipolar 380 V, CMOS 250 V, EPROM 100 V)?', 'Một người chỉ mang 200 V. Linh kiện nào dưới đây vẫn có thể bị hỏng (điện áp gây hỏng thấp nhất: lưỡng cực 380 V, CMOS 250 V, EPROM 100 V)?'),
  [('EPROMs only', 'Chỉ EPROM'), ('CMOS devices only', 'Chỉ CMOS'), ('Bipolar transistors and EPROMs', 'Transistor lưỡng cực và EPROM'), ('All three types', 'Cả ba loại')],
  ('200 V exceeds the 100 V of EPROMs but not the 250 V of CMOS or the 380 V of bipolar transistors.', '200 V vượt 100 V của EPROM nhưng không vượt 250 V của CMOS hay 380 V của transistor lưỡng cực.'))
Q(ST, 93, r'Class\s+II\s+for\s+1\s*001\s+to\s+4\s*000', ('A device is damaged only by discharges of about 2,500 V or more. In MIL-STD-1686C it belongs to', 'Một linh kiện chỉ bị hỏng khi phóng điện khoảng 2.500 V trở lên. Theo MIL-STD-1686C nó thuộc'),
  [('Class II (1,001 to 4,000 V)', 'Lớp II (1.001 đến 4.000 V)'), ('Class I (100 to 1,000 V)', 'Lớp I (100 đến 1.000 V)'), ('Neither class: the standard stops at 1,000 V', 'Không lớp nào: tiêu chuẩn dừng ở 1.000 V'), ('Class III (above 4,000 V)', 'Lớp III (trên 4.000 V)')],
  ('The standard recognizes two classes by sensitivity: Class I for 100 to 1,000 V and Class II for 1,001 to 4,000 V; 2,500 V falls in Class II (most components are in Class I).', 'Tiêu chuẩn có hai lớp theo độ nhạy: Lớp I 100–1.000 V và Lớp II 1.001–4.000 V; 2.500 V thuộc Lớp II (đa số linh kiện thuộc Lớp I).'))
Q(ST, 93, r'Most\s+electronic\s+components\s+are\s+in\s+Class\s+I', ('Most electronic components are in MIL-STD-1686C Class I. This means that', 'Đa số linh kiện điện tử thuộc Lớp I của MIL-STD-1686C. Điều đó có nghĩa là'),
  [('they can be damaged by discharges of only 100 to 1,000 V', 'chúng có thể bị hỏng chỉ với phóng điện 100 đến 1.000 V'), ('they tolerate 1,001 to 4,000 V without damage', 'chúng chịu được 1.001 đến 4.000 V mà không hỏng'), ('they need no ESD control at the work station', 'chúng không cần kiểm soát ESD tại bàn làm việc'), ('they are damaged only by induction, never by contact', 'chúng chỉ bị hỏng do cảm ứng, không bao giờ do tiếp xúc')],
  ('Class I covers the most sensitive items (100 to 1,000 V), and most components are in it, so ordinary handling voltages are enough to damage them.', 'Lớp I gồm các linh kiện nhạy nhất (100–1.000 V) và đa số linh kiện thuộc lớp này, nên điện áp xử lý thông thường cũng đủ làm hỏng.'))
Q(ST, 93, r'through\s+induction\s+from\s+an\s+electromagnetic\s+field,\s+or\s+through\s+conduction\s+via\s+physical\s+contact', ('According to the definition, an electrostatic charge can pass from one body to another by', 'Theo định nghĩa, điện tích tĩnh có thể truyền từ vật này sang vật khác bằng'),
  [('conduction through physical contact or induction from a field', 'dẫn điện qua tiếp xúc hoặc cảm ứng từ một trường'), ('convection in moving air or radiation as light', 'đối lưu trong không khí chuyển động hoặc bức xạ ánh sáng'), ('conduction only: a charge cannot act at a distance', 'chỉ dẫn điện: điện tích không tác động từ xa được'), ('induction only: contact discharges are harmless', 'chỉ cảm ứng: phóng điện do tiếp xúc vô hại')],
  ('ESD is the transfer of charge between bodies at different potentials, caused by direct contact or induced by an electrostatic field.', 'ESD là sự truyền điện tích giữa các vật có điện thế khác nhau, do tiếp xúc trực tiếp hoặc do trường tĩnh điện cảm ứng.'))
Q(ST, 93, r'component\s+will\s+be\s+damaged\s+due\s+to\s+excessive\s+heat', ('A charged component is suddenly grounded. What happens?', 'Một linh kiện đang tích điện đột ngột được nối đất. Điều gì xảy ra?'),
  [('The charge flows to ground but the component can be damaged by excessive heat or dielectric breakdown', 'Điện tích thoát xuống đất nhưng linh kiện có thể hỏng do quá nhiệt hoặc đánh thủng điện môi'), ('It is safely discharged: grounding never harms a component', 'Nó được xả an toàn: nối đất không bao giờ làm hại linh kiện'), ('The charge stays on the part because insulators cannot discharge', 'Điện tích ở lại trên linh kiện vì chất cách điện không xả được'), ('The component becomes permanently magnetized', 'Linh kiện bị nhiễm từ vĩnh viễn')],
  ('The sudden discharge dissipates the charge to ground, but in the process the part is damaged by heat and/or breakdown of its internal dielectric.', 'Xả đột ngột làm điện tích thoát xuống đất, nhưng đồng thời linh kiện bị hỏng do nhiệt và/hoặc đánh thủng điện môi bên trong.'))
Q(ST, 93, r'side\s+of\s+the\s+paper\s+closest\s+to\s+the\s+comb\s+will\s+end\s+up\s+being\s+slightly\s+positive', ('In the comb-and-paper example the comb is charged negative. The side of the paper closest to the comb becomes', 'Trong ví dụ chiếc lược và mẩu giấy, lược tích điện âm. Mặt giấy gần lược nhất trở nên'),
  [('slightly positive (opposite charges attract)', 'hơi dương (điện tích trái dấu hút nhau)'), ('slightly negative', 'hơi âm'), ('neutral, because paper is an insulator', 'trung hòa, vì giấy là chất cách điện'), ('strongly negative', 'âm mạnh')],
  ('Electrostatic induction redistributes charge: the near side is attracted to positive, the far side repelled to negative, so the paper is pulled to the comb.', 'Cảm ứng tĩnh điện làm điện tích phân bố lại: mặt gần bị hút thành dương, mặt xa bị đẩy thành âm, nên giấy bị hút về phía lược.'))
Q(ST, 94, r'physical\s+geometries\s+are\s+shrinking', ('Why do newer components need stronger ESD precautions than older ones?', 'Vì sao linh kiện mới cần phòng ngừa ESD chặt chẽ hơn linh kiện cũ?'),
  [('Shrinking geometries make them susceptible to lower discharge voltages', 'Kích thước nhỏ đi khiến chúng nhạy với điện áp phóng thấp hơn'), ('Larger geometries store more charge', 'Kích thước lớn hơn tích nhiều điện tích hơn'), ('They contain more metal that attracts charge', 'Chúng chứa nhiều kim loại hơn nên hút điện tích'), ('They are packaged only in plastic', 'Chúng chỉ được đóng gói bằng nhựa')],
  ('As components get faster and more capable their geometries shrink, so they become susceptible to ever lower discharge voltages: the ESD problem is getting worse, not better.', 'Khi linh kiện nhanh hơn và nhiều chức năng hơn, kích thước thu nhỏ nên chúng nhạy với điện áp phóng ngày càng thấp: vấn đề ESD ngày càng nghiêm trọng.'))
Q(ST, 93, r'The\s+faster\s+the\s+person\s+walks,\s+the\s+higher\s+the\s+charge', ('Which action increases the static charge on a technician the most?', 'Hành động nào làm tăng điện tích tĩnh trên người kỹ thuật viên nhiều nhất?'),
  [('Walking fast across an ordinary floor when the humidity is below 20 %', 'Đi nhanh trên sàn thường khi độ ẩm dưới 20 %'), ('Standing still in humid air', 'Đứng yên trong không khí ẩm'), ('Sitting at the bench wearing a grounded wrist strap', 'Ngồi ở bàn làm việc có đeo dây nối đất'), ('Walking slowly on a conductively coated floor', 'Đi chậm trên sàn phủ lớp dẫn điện')],
  ('Friction builds the charge; it grows as humidity drops below 20 % and the faster the person walks, while conductive floors and a grounded strap let it leak away.', 'Ma sát tạo điện tích; điện tích tăng khi độ ẩm xuống dưới 20 % và khi đi nhanh hơn, còn sàn dẫn điện và dây nối đất cho điện tích thoát đi.'))
r = 5000 / 250; assert r == 20
Q(ST, 93, r'Plastics\s+used\s+in\s+most\s+products\s+will\s+produce\s+charges\s+from\s+5\s*000\s+to\s+10\s*000', ('Plastics produce charges of 5,000 to 10,000 V. Compared with the lowest damaging voltage of a CMOS device (250 V), such a charge is at least', 'Nhựa tạo điện tích 5.000 đến 10.000 V. So với điện áp gây hỏng thấp nhất của linh kiện CMOS (250 V), điện tích đó lớn gấp ít nhất'),
  [('20 times larger', '20 lần'), ('2 times larger', '2 lần'), ('200 times larger', '200 lần'), ('40 times larger', '40 lần')],
  ('5,000 V ÷ 250 V = 20 at the very least (10,000 V gives 40): a plastic item near a CMOS part is far above its damage level.', '5.000 V ÷ 250 V = 20 ít nhất (10.000 V cho 40): vật bằng nhựa gần linh kiện CMOS vượt xa mức gây hỏng.'))
# ------------------------------------------------------------------ ESD protection and handling (p.2.7-2.8, PDF 94-95)
Q(ES, 94, r'The\s+resistor\s+is\s+required\s+to\s+protect\s+personnel', ('What does the 1 MΩ resistor in the grounding path of a mat or wrist strap do if the ground becomes electrically live?', 'Điện trở 1 MΩ trong đường nối đất của thảm hoặc dây đeo cổ tay có tác dụng gì nếu đất bất ngờ mang điện?'),
  [('It limits the current through the person and so protects the personnel', 'Nó hạn chế dòng qua người và nhờ đó bảo vệ người làm việc'), ('It drains the static charge faster than a direct wire', 'Nó xả điện tích tĩnh nhanh hơn dây nối trực tiếp'), ('It ionizes the air around the work station', 'Nó ion hoá không khí quanh bàn làm việc'), ('It measures the charge on the wrist', 'Nó đo điện tích trên cổ tay')],
  ('The resistor is required to protect personnel in the event the ground becomes electrically live: it keeps a fault current through the body small (230 V across 1 MΩ is only 0.23 mA).', 'Điện trở bắt buộc để bảo vệ người nếu đất mang điện: nó giữ dòng sự cố qua cơ thể nhỏ (230 V trên 1 MΩ chỉ là 0,23 mA).'))
Q(ES, 94, r'grounding\s+cord\s+must\s+run\s+into\s+the\s+sock', ('A technician uses a heel strap instead of conductive shoes. For it to work', 'Một kỹ thuật viên dùng dây đeo gót thay cho giày dẫn điện. Để nó hoạt động'),
  [('the grounding cord must run into the sock to touch the skin', 'dây nối đất phải luồn vào trong tất để chạm da'), ('the cord must be wound around the outside of a rubber sole', 'dây phải quấn quanh bên ngoài đế cao su'), ('no skin contact is needed because the shoe conducts', 'không cần chạm da vì giày dẫn điện'), ('the strap must be worn on the wrist as well', 'cũng phải đeo dây ở cổ tay')],
  ('The charge must be able to leave the body, so the grounding cord has to make contact with the skin inside the sock.', 'Điện tích phải thoát khỏi cơ thể nên dây nối đất phải tiếp xúc với da bên trong tất.'))
Q(ES, 94, r'surface\s+resistivity\s+of\s+10\s*5\s+to\s+10\s*12', ('A static-dissipative mat must have a surface resistivity of 10⁵ to 10¹² ohms per square inch. Which value qualifies?', 'Thảm tiêu tán tĩnh điện phải có điện trở suất bề mặt từ 10⁵ đến 10¹² ôm trên inch vuông. Giá trị nào đạt?'),
  [('10⁸ Ω per square inch', '10⁸ Ω trên inch vuông'), ('10² Ω per square inch (as conductive as metal)', '10² Ω trên inch vuông (dẫn điện như kim loại)'), ('10¹⁵ Ω per square inch (an insulator)', '10¹⁵ Ω trên inch vuông (chất cách điện)'), ('10³ Ω per square inch', '10³ Ω trên inch vuông')],
  ('Only 10⁸ lies inside the 10⁵ to 10¹² range: dissipative enough to bleed charge away without being a short circuit, and not an insulator that would store it.', 'Chỉ 10⁸ nằm trong khoảng 10⁵ đến 10¹²: đủ dẫn để xả điện tích mà không như đoản mạch, và không phải chất cách điện tích điện.'))
Q(ES, 94, r'must\s+also\s+remove\s+the\s+static\s+charge\s+from\s+conductive\s+items', ('Besides giving a surface free of static charge, a conductive table-top mat must also', 'Ngoài việc tạo mặt bàn không có điện tích tĩnh, thảm dẫn điện còn phải'),
  [('remove the static charge from conductive items placed on it', 'xả điện tích tĩnh khỏi các vật dẫn điện đặt lên nó'), ('insulate the components from ground', 'cách ly linh kiện khỏi đất'), ('generate ions to neutralize insulators', 'tạo ion để trung hòa chất cách điện'), ('store the charge for later measurement', 'lưu điện tích để đo sau')],
  ('The mat is connected through 1 MΩ to a common ground point so that charge on items resting on it drains away.', 'Thảm được nối qua 1 MΩ tới điểm đất chung để điện tích trên các vật đặt lên nó thoát đi.'))
Q(ES, 94, r'A\s+green\s+indicator\s+light\s+means\s+that\s+the\s+wrist\s+strap', ('A technician tests a wrist strap at the grounding test station and the green light does not come on. What should he conclude?', 'Kỹ thuật viên kiểm tra dây đeo cổ tay ở trạm thử nối đất và đèn xanh không sáng. Anh ấy nên kết luận gì?'),
  [('The strap is not worn properly or not working; fix or replace it before entering the controlled area', 'Dây không đeo đúng hoặc không hoạt động; sửa hoặc thay trước khi vào khu vực kiểm soát'), ('The strap is fine: green only means the station has power', 'Dây vẫn tốt: đèn xanh chỉ báo trạm có điện'), ('He may enter and test again later at the bench', 'Anh ấy có thể vào rồi thử lại sau ở bàn làm việc'), ('Only footwear needs to be tested, not straps', 'Chỉ cần thử giày dép, không cần thử dây đeo')],
  ('All anti-static devices are tested before entering the controlled environment; green means the strap is worn properly and working as intended, so no green light means it is not.', 'Mọi thiết bị chống tĩnh điện được thử trước khi vào khu vực kiểm soát; đèn xanh nghĩa là dây đeo đúng và hoạt động, không có đèn xanh nghĩa là chưa đạt.'))
Q(ES, 94, r'test\s+footwear,\s+heal\s+straps,\s+and\s+coil\s+cords', ('Besides wrist straps, a grounding test station can also be used to test', 'Ngoài dây đeo cổ tay, trạm thử nối đất còn dùng để thử'),
  [('footwear, heel straps and coil cords', 'giày dép, dây đeo gót và dây xoắn'), ('ionizers and field meters', 'máy ion hoá và đồng hồ đo trường'), ('conductive bags and totes', 'túi và hộp dẫn điện'), ('soldering irons only', 'chỉ mỏ hàn')],
  ('The same station checks footwear, heel straps and coil cords, i.e. every personal grounding path.', 'Cùng một trạm kiểm tra giày dép, dây đeo gót và dây xoắn, tức mọi đường nối đất cá nhân.'))
Q(ES, 95, r'air\s+stream\s+containing\s+both\s+positive\s+and\s+negative\s+ions', ('How does an ionizer neutralize a charged insulating surface?', 'Máy ion hoá trung hòa bề mặt cách điện đang tích điện như thế nào?'),
  [('An air stream with positive and negative ions lets the surface attract the ions of opposite charge', 'Luồng khí chứa ion dương và âm cho bề mặt hút các ion trái dấu'), ('It heats the surface until the charge evaporates', 'Nó làm nóng bề mặt cho điện tích bốc hơi'), ('It sprays water mist to raise the humidity to 100 %', 'Nó phun sương nước để độ ẩm lên 100 %'), ('It generates a strong magnetic field', 'Nó tạo từ trường mạnh')],
  ('Positively or negatively charged surfaces attract ions of the opposite charge; once neutralized the surface stays so as long as the ion stream is present.', 'Bề mặt tích điện dương hoặc âm hút ion trái dấu; khi đã trung hòa, bề mặt giữ trạng thái đó chừng nào luồng ion còn.'))
lo, hi = 30 * 2.54, 36 * 2.54; assert round(lo) == 76 and round(hi) == 91
Q(ES, 95, r'mounted\s+30"?\s*-?\s*36"?\s+above', ('A work-station ionizer is normally mounted 30 to 36 inches above the area to be controlled. In centimetres this is about', 'Máy ion hoá tại bàn làm việc thường lắp cao 30 đến 36 inch so với khu vực cần kiểm soát. Tính ra centimet là khoảng'),
  [('76 to 91 cm', '76 đến 91 cm'), ('30 to 36 cm', '30 đến 36 cm'), ('300 to 360 cm', '300 đến 360 cm'), ('50 to 60 cm', '50 đến 60 cm')],
  ('1 inch = 2.54 cm: 30 × 2.54 = 76.2 cm and 36 × 2.54 = 91.4 cm.', '1 inch = 2,54 cm: 30 × 2,54 = 76,2 cm và 36 × 2,54 = 91,4 cm.'))
area = 36 * 48 * 0.0254 ** 2; assert abs(area - 1.115) < 0.001
Q(ES, 95, r'approximately\s+36"?\s*wide\s+x\s+48"?\s*long', ('The ionization pattern of an overhead ionizer is about 36 inches wide by 48 inches long. Its area is about', 'Vùng ion hoá của máy ion hoá treo trên cao rộng khoảng 36 inch và dài 48 inch. Diện tích của nó khoảng'),
  [('1.1 m²', '1,1 m²'), ('0.11 m²', '0,11 m²'), ('11 m²', '11 m²'), ('1.7 m²', '1,7 m²')],
  ('36 in × 48 in = 1,728 in²; each in² is 6.45·10⁻⁴ m², so about 1.1 m² (a bench-sized area).', '36 in × 48 in = 1.728 in²; mỗi in² là 6,45·10⁻⁴ m², nên khoảng 1,1 m² (cỡ một mặt bàn).'))
Q(ES, 95, r'electrostatic\s+field\s+meter\s+to\s+detect\s+static\s+charges', ('Before handling sensitive components, how should a technician make sure the ionizer is working?', 'Trước khi xử lý linh kiện nhạy, kỹ thuật viên làm thế nào để chắc chắn máy ion hoá đang hoạt động?'),
  [('Use an electrostatic field meter to detect static charges in the work area', 'Dùng đồng hồ đo trường tĩnh điện để dò điện tích tĩnh trong khu vực làm việc'), ('Listen for the fan noise', 'Nghe tiếng quạt'), ('Touch a grounded rack with a bare hand', 'Chạm tay trần vào giá nối đất'), ('Check that the room is at 65 % humidity', 'Kiểm tra phòng có độ ẩm 65 %')],
  ('The text recommends an electrostatic field meter to be assured that the ionizer is functioning properly before sensitive parts are handled.', 'Sách khuyến nghị dùng đồng hồ đo trường tĩnh điện để chắc chắn máy ion hoá hoạt động tốt trước khi xử lý linh kiện nhạy.'))
Q(ES, 95, r'high-pressure,\s+low-volume\s+air\s+guns\s+for\s+periodic\s+localized\s+cleaning', ('Which type of ionizer is meant for periodic, localized cleaning?', 'Loại máy ion hoá nào dùng để làm sạch cục bộ định kỳ?'),
  [('A high-pressure, low-volume air gun', 'Súng khí áp suất cao, lưu lượng nhỏ'), ('A low-pressure, high-volume wall-mounted unit', 'Thiết bị gắn tường áp suất thấp, lưu lượng lớn'), ('A topical anti-stat spray', 'Dung dịch xịt chống tĩnh điện'), ('An overhead sign', 'Biển báo treo trên cao')],
  ('Air guns are the high-pressure, low-volume type for localized cleaning; the low-pressure, high-volume units hang over the work station and blow ionized air down on the area.', 'Súng khí là loại áp suất cao, lưu lượng nhỏ cho làm sạch cục bộ; loại áp suất thấp, lưu lượng lớn treo trên bàn và thổi khí ion xuống khu vực.'))
Q(ES, 95, r'it\s+must\s+make\s+contact\s+with\s+the\s+grounded\s+table\s+mat', ('A closed conductive container of ESD-sensitive parts is brought from its rack to the work station. When it arrives it must', 'Hộp dẫn điện kín chứa linh kiện nhạy ESD được mang từ giá tới bàn làm việc. Khi tới nơi nó phải'),
  [('make contact with the grounded table mat', 'tiếp xúc với thảm bàn đã nối đất'), ('be opened at once on any desk', 'được mở ngay trên bất kỳ bàn nào'), ('be placed on a plastic tray', 'được đặt trên khay nhựa'), ('be wrapped in a nylon cloth', 'được bọc vải ni lông')],
  ('The container is stored on a grounded rack and, at the bench, touches the grounded mat so its charge equalizes with ground before it is opened.', 'Hộp được cất trên giá nối đất và khi ở bàn thì chạm vào thảm nối đất để điện tích cân bằng với đất trước khi mở.'))
Q(ES, 95, r'should\s+first\s+be\s+discharged,\s+by\s+wearing', ('Which sequence is correct for installing an ESD-sensitive part taken from a protective container?', 'Trình tự nào đúng để lắp một linh kiện nhạy ESD lấy từ hộp bảo vệ?'),
  [('Put on the grounded wrist strap to discharge the body, open the container, install with a grounded soldering iron', 'Đeo dây nối đất để xả điện cơ thể, mở hộp, lắp bằng mỏ hàn nối đất'), ('Open the container, then put on the wrist strap, then install with an ordinary soldering iron', 'Mở hộp, rồi đeo dây, rồi lắp bằng mỏ hàn thường'), ('Install with a grounded iron, then discharge the body, then open the container', 'Lắp bằng mỏ hàn nối đất, rồi xả điện cơ thể, rồi mở hộp'), ('Open the container, install, then test the wrist strap', 'Mở hộp, lắp, rồi thử dây đeo')],
  ('Charge on the body is discharged first (grounded strap), only then is the protective container opened, and a grounded soldering iron is used for installation.', 'Xả điện cơ thể trước (dây nối đất), sau đó mới mở hộp bảo vệ và dùng mỏ hàn nối đất khi lắp.'))
Q(ES, 95, r'outer\s+layer\s+of\s+transparent\s+metalized\s+sheet', ('From the outside to the inside, an electrostatic-shielded conductive bag is made of', 'Từ ngoài vào trong, túi dẫn điện che chắn tĩnh điện gồm'),
  [('a metalized sheet or aluminum foil, an insulation layer, then an anti-static layer', 'lớp màng kim loại hoặc lá nhôm, lớp cách điện, rồi lớp chống tĩnh điện'), ('an anti-static layer, an insulation layer, then a metalized sheet', 'lớp chống tĩnh điện, lớp cách điện, rồi lớp màng kim loại'), ('an insulation layer, a metalized sheet, then an anti-static layer', 'lớp cách điện, lớp màng kim loại, rồi lớp chống tĩnh điện'), ('a metalized sheet, an anti-static layer, then an insulation layer', 'lớp màng kim loại, lớp chống tĩnh điện, rồi lớp cách điện')],
  ('The bag is laminated: outer transparent metalized sheet or aluminum foil, a middle insulation layer and an inner anti-static layer that touches the part.', 'Túi nhiều lớp: ngoài là màng kim loại trong suốt hoặc lá nhôm, giữa là lớp cách điện, trong là lớp chống tĩnh điện tiếp xúc với linh kiện.'))
Q(ES, 94, r'Signage\s+must\s+be\s+placed\s+outside\s+any\s+ESD\s+controlled', ('Where must the warning signs for an ESD-controlled area be placed?', 'Biển cảnh báo khu vực kiểm soát ESD phải đặt ở đâu?'),
  [('Outside the controlled area, so people are warned before they enter', 'Bên ngoài khu vực kiểm soát để cảnh báo trước khi người ta vào'), ('Only on the component bags', 'Chỉ trên các túi linh kiện'), ('Inside the ionizer housing', 'Bên trong vỏ máy ion hoá'), ('On the wrist strap', 'Trên dây đeo cổ tay')],
  ('Signage is placed outside any ESD-controlled area to warn people that special precautions are needed before they go in.', 'Biển báo đặt bên ngoài mọi khu vực kiểm soát ESD để cảnh báo cần có biện pháp đặc biệt trước khi vào.'))
Q(ES, 94, r'nylon,\s+mylar,\s+vinyl,\s+rubber,\s+mica,\s+ceramics', ('Which of these is NOT named in the text as an insulating material that stores static electricity and must be kept out of the work area?', 'Vật liệu nào dưới đây KHÔNG được sách nêu là chất cách điện tích tĩnh điện cần để ngoài khu vực làm việc?'),
  [('Copper', 'Đồng'), ('Styrofoam', 'Xốp polystyrene'), ('Mica', 'Mica'), ('Fiberglass', 'Sợi thủy tinh')],
  ('The list is nylon, mylar, vinyl, rubber, mica, ceramics, fiberglass, wood, styrofoam and plastic; copper is a conductor, and conductive materials are grounded instead.', 'Danh sách gồm nylon, mylar, vinyl, cao su, mica, gốm, sợi thủy tinh, gỗ, xốp và nhựa; đồng là chất dẫn điện, vật dẫn điện được nối đất.'))
# ------------------------------------------------------------------ mounting technologies and soldering (p.2.3-2.4, PDF 90-91)
Q(MT, 90, r'allows\s+more\s+components\s+and\s+circuits\s+to\s+be\s+placed\s+on\s+the\s+same\s+PCB', ('Which technology lets more components fit on the same PCB, and what is its drawback?', 'Công nghệ nào cho nhiều linh kiện hơn trên cùng một PCB, và nhược điểm của nó là gì?'),
  [('Surface mount: both sides can be used, but alignment and soldering are harder', 'Dán bề mặt: dùng được cả hai mặt nhưng khó căn chỉnh và hàn hơn'), ('Through hole: both sides can be used, but it needs special equipment', 'Xuyên lỗ: dùng được cả hai mặt nhưng cần thiết bị đặc biệt'), ('BGA: a simple iron is enough, but pin density is low', 'BGA: chỉ cần mỏ hàn đơn giản nhưng mật độ chân thấp'), ('Plated through hole: the cheapest and quickest to make', 'Lỗ mạ xuyên: rẻ nhất và nhanh làm nhất')],
  ('SMT parts sit on the trace side and on both faces, so the density is higher; the only disadvantage given is that SMT components are more difficult to align and solder.', 'Linh kiện SMT nằm trên mặt có đường mạch và dùng được cả hai mặt nên mật độ cao hơn; nhược điểm duy nhất nêu là khó căn chỉnh và hàn.'))
Q(MT, 90, r'higher\s+pin\s+density\s+compared\s+to\s+other', ('The text describes BGA packages as having', 'Sách mô tả gói BGA là có'),
  [('higher pin density, but they need special equipment instead of a simple soldering iron', 'mật độ chân cao hơn, nhưng cần thiết bị đặc biệt thay cho mỏ hàn đơn giản'), ('lower pin density and easy hand soldering', 'mật độ chân thấp và dễ hàn tay'), ('leads that pass through plated holes', 'chân luồn qua các lỗ mạ'), ('no solder because they are glued', 'không dùng thiếc vì được dán keo')],
  ('Solder balls under the component give more connections in less space; installing or removing them needs special equipment.', 'Các viên thiếc dưới linh kiện cho nhiều kết nối hơn trong diện tích nhỏ hơn; lắp hoặc tháo chúng cần thiết bị đặc biệt.'))
Q(MT, 91, r'in\s+molten\s+tin\s+solder\s+and\s+the\s+solder\s+is\s+sucked\s+up', ('Leaded components are inserted into holes and the board is dipped in molten solder. This is', 'Linh kiện có chân được cắm vào lỗ rồi bo mạch được nhúng vào thiếc nóng chảy. Đó là'),
  [('flow soldering with through-hole components', 'hàn dòng (flow) với linh kiện xuyên lỗ'), ('reflow soldering', 'hàn nung chảy (reflow)'), ('hand soldering with an iron', 'hàn tay bằng mỏ hàn'), ('ball-grid-array bonding', 'liên kết BGA')],
  ('In flow soldering the board moves on a conveyor and is dipped in molten tin; the solder is drawn up through the plated-through holes to form the joints.', 'Trong hàn dòng, bo mạch đi trên băng tải và được nhúng thiếc nóng chảy; thiếc dâng lên qua lỗ mạ để tạo mối hàn.'))
Q(MT, 91, r'held\s+in\s+place\s+with\s+an\s+adhesive', ('Chip components are placed on solder-paste pads, held by an adhesive and heated in a controlled oven. This is', 'Linh kiện chip được đặt lên các chân có kem hàn, giữ bằng keo dính rồi nung trong lò có kiểm soát. Đó là'),
  [('reflow soldering (surface mount)', 'hàn nung chảy (reflow, dán bề mặt)'), ('flow soldering', 'hàn dòng (flow)'), ('hand soldering with an iron', 'hàn tay bằng mỏ hàn'), ('wire wrapping', 'quấn dây')],
  ('Solder paste is applied to the copper pads, parts are picked and placed and held by adhesive, then a reflow oven melts the paste to form the electrical connection and mechanical bond.', 'Kem hàn bôi lên chân đồng, linh kiện được gắp đặt và giữ bằng keo, rồi lò reflow làm chảy kem hàn tạo kết nối điện và liên kết cơ học.'))
Q(MT, 90, r'less\s+expensive\s+and\s+take\s+less\s+time\s+to\s+manufacture', ('Which statement about non-plated and plated through holes is correct?', 'Phát biểu nào về lỗ xuyên không mạ và lỗ mạ xuyên là đúng?'),
  [('Non-plated holes are cheaper and quicker to make but give less conductivity and stiffness at the joint', 'Lỗ không mạ rẻ và nhanh làm hơn nhưng độ dẫn điện và độ cứng ở mối nối kém hơn'), ('Non-plated holes are more expensive but conduct better', 'Lỗ không mạ đắt hơn nhưng dẫn tốt hơn'), ('Plated and non-plated holes differ only in diameter', 'Lỗ mạ và không mạ chỉ khác đường kính'), ('Plated holes have more resistivity at the joint', 'Lỗ mạ có điện trở suất ở mối nối lớn hơn')],
  ('Copper inside the hole is what makes the difference: lower resistivity and some mechanical stiffness, at the price of a more expensive and slower process.', 'Lớp đồng trong lỗ tạo ra khác biệt: điện trở suất thấp hơn và có độ cứng cơ học, đổi lại quy trình đắt và chậm hơn.'))
# ------------------------------------------------------------------ multilayer boards and vias (p.2.4-2.5, PDF 91-92)
Q(ML, 92, r'buried\s+vias\s+\(3\)\s+that\s+connect\s+internal\s+layers', ('A via must join layers 2 and 3 of a multi-layer board and be invisible from both outer surfaces. It is a', 'Một via phải nối lớp 2 và lớp 3 của PCB nhiều lớp và không lộ ra cả hai mặt ngoài. Đó là via'),
  [('buried via', 'chôn (buried)'), ('blind via', 'mù (blind)'), ('through-hole via', 'xuyên lỗ (through-hole)'), ('thermal via', 'tản nhiệt (thermal)')],
  ('A buried via connects internal layers without being exposed to either surface.', 'Via chôn nối các lớp bên trong mà không lộ ra mặt nào.'))
Q(ML, 92, r'blind\s+vias\s+\(2\)\s+that\s+are\s+exposed\s+to\s+only\s+one\s+side', ('A via starts on the top surface and stops at an inner layer without reaching the bottom surface. It is a', 'Một via bắt đầu từ mặt trên và dừng ở lớp trong, không tới mặt dưới. Đó là via'),
  [('blind via', 'mù (blind)'), ('buried via', 'chôn (buried)'), ('through-hole via', 'xuyên lỗ (through-hole)'), ('thermal via', 'tản nhiệt (thermal)')],
  ('A blind via is exposed to only one side of the board.', 'Via mù chỉ lộ ra một mặt của bo mạch.'))
Q(ML, 92, r'Thermal\s+vias\s+are\s+used\s+to\s+carry\s+heat\s+away', ('A power transistor on a multi-layer board runs too hot. Which feature of the board helps carry its heat away?', 'Một transistor công suất trên PCB nhiều lớp quá nóng. Đặc điểm nào của bo mạch giúp dẫn nhiệt đi?'),
  [('An array of thermal vias', 'Một dãy via tản nhiệt'), ('A blind via to the top layer only', 'Một via mù chỉ tới lớp trên'), ('More solder balls under the part', 'Thêm viên thiếc dưới linh kiện'), ('A thicker protective laminate', 'Lớp phủ bảo vệ dày hơn')],
  ('Thermal vias are used to carry heat away from power devices and are typically arranged in an array.', 'Via tản nhiệt dùng để dẫn nhiệt khỏi linh kiện công suất và thường được bố trí thành dãy.'))
Q(ML, 92, r'unintended\s+capacitive\s+and\s+inductive', ('Why is computer modelling used when designing high-frequency multi-layer boards?', 'Vì sao dùng mô hình máy tính khi thiết kế PCB nhiều lớp tần số cao?'),
  [('To limit unintended capacitive and inductive coupling between the layers', 'Để hạn chế ghép điện dung và điện cảm không mong muốn giữa các lớp'), ('To reduce the number of vias to zero', 'Để giảm số via xuống 0'), ('To avoid the need for copper traces', 'Để khỏi cần các đường đồng'), ('To make the board thicker', 'Để làm bo mạch dày hơn')],
  ('As designs become more complex, unintended coupling mechanisms appear between layers, particularly at high frequency; modelling is used to mitigate them.', 'Khi thiết kế phức tạp hơn, các cơ chế ghép không mong muốn xuất hiện giữa các lớp, nhất là ở tần số cao; mô hình hóa dùng để giảm chúng.'))
# ------------------------------------------------------------------ PCB construction and repair (p.2.2, 2.5; PDF 89, 92)
Q(PC, 89, r'heat\s+press\s+operation', ('Which order of the PCB manufacturing steps described in the text is correct?', 'Thứ tự các bước chế tạo PCB mô tả trong sách là thế nào?'),
  [('Bond copper foil (heat press), print the pattern in etch-resistive ink, etch away the unwanted copper', 'Dán lá đồng (ép nhiệt), in mẫu bằng mực chống ăn mòn, ăn mòn bỏ đồng thừa'), ('Etch the copper, bond the foil, then print the ink pattern', 'Ăn mòn đồng, dán lá đồng, rồi in mẫu mực'), ('Print the ink pattern, etch, then bond the copper foil', 'In mẫu mực, ăn mòn, rồi dán lá đồng'), ('Etch the copper, print the ink pattern, then bond the foil', 'Ăn mòn đồng, in mẫu mực, rồi dán lá đồng')],
  ('The foil is bonded to the board in a heat press, the circuit pattern is applied with etch-resistive ink, and the chemical etch removes the copper not protected by the ink.', 'Lá đồng được ép nhiệt lên bo mạch, mẫu mạch in bằng mực chống ăn mòn, rồi ăn mòn hóa học bỏ phần đồng không được mực che.'))
Q(PC, 89, r'unwanted\s+copper\s+is\s+etched\s+away', ('After etching, what remains of the copper foil?', 'Sau khi ăn mòn, phần nào của lá đồng còn lại?'),
  [('Only the pattern protected by the etch-resistive ink: the traces', 'Chỉ phần mẫu được mực chống ăn mòn che: các đường mạch (traces)'), ('The whole foil, now thinner', 'Toàn bộ lá đồng nhưng mỏng hơn'), ('Only the copper under the components', 'Chỉ phần đồng dưới linh kiện'), ('Nothing: the traces are added afterwards as wire', 'Không còn gì: đường mạch được thêm sau bằng dây')],
  ('The unwanted copper is etched away by a photosensitive chemical process (ammonium persulfate or ferric chloride), leaving only the conductive pathways called traces.', 'Đồng thừa bị ăn mòn bằng quá trình hóa học cảm quang (amoni persunfat hoặc sắt(III) clorua), chỉ còn các đường dẫn gọi là traces.'))
Q(RP, 92, r'should\s+not\s+performed\s+in\s+the\s+field', ('A printed circuit board in an aircraft system is defective. What does the text recommend?', 'Một bo mạch in trong hệ thống máy bay bị hỏng. Sách khuyến nghị gì?'),
  [('Replace the removable module (LRM) and repair the board in an equipped shop', 'Thay mô-đun tháo được (LRM) và sửa bo mạch trong xưởng có đủ thiết bị'), ('Re-solder the joints in the field with a simple iron', 'Hàn lại mối nối ngay hiện trường bằng mỏ hàn đơn giản'), ('Scrape off the protective laminate and repair it on the aircraft', 'Cạo lớp phủ bảo vệ và sửa ngay trên máy bay'), ('Leave it: printed circuit boards cannot be repaired', 'Bỏ qua: bo mạch in không sửa được')],
  ('Soldering needs special equipment with precise heat control and should not be done in the field; Line Replaceable Modules allow replacement of defective units, with repair by knowledgeable technicians in an equipped shop.', 'Hàn cần thiết bị đặc biệt có kiểm soát nhiệt chính xác, không nên làm ở hiện trường; LRM cho phép thay đơn vị hỏng, việc sửa do kỹ thuật viên có hiểu biết thực hiện trong xưởng đủ thiết bị.'))
